 29	    private static volatile String translogBody = "{\"price_cents\":3310,\"eta_hours\":41}";
 30	    private static volatile int translogStatus = 200;
 31	    private static final HttpServer TRANSLOG = startTranslog();
 32	
 33	    private static HttpServer startTranslog() {
 34	        try {
 35	            HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
 36	            server.createContext("/v2/quote", exchange -> {
 37	                byte[] body = translogBody.getBytes(StandardCharsets.UTF_8);
 38	                exchange.sendResponseHeaders(translogStatus, body.length);
 39	                exchange.getResponseBody().write(body);
 40	                exchange.close();
 41	            });
 42	            server.start();
 43	            return server;
 44	        } catch (IOException e) {
 45	            throw new IllegalStateException(e);
 46	        }
 47	    }
