 81	    record Reply(int status, Map<String, Object> json) {
 82	        @SuppressWarnings("unchecked")
 83	        Map<String, Object> map(String key) {
 84	            return (Map<String, Object>) json.get(key);
 85	        }
 86	    }
 87	
 88	    @SuppressWarnings("unchecked")
 89	    private Reply call(String method, String path, String body) throws Exception {
 90	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create("http://localhost:" + port + path))
 91	                .header("Content-Type", "application/json");
 92	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 93	        HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 94	        Map<String, Object> json = r.body().isBlank() ? Map.of() : mapper.readValue(r.body(), Map.class);
 95	        return new Reply(r.statusCode(), json);
 96	    }
