 98	    private static String purchase(String items, String shipping, String coupon, String payment, int installments,
 99	                                   String tier, String region) {
100	        return """
101	                {"customer":{"cpf":"12345678909","email":"ana@exemplo.com"},"items":%s,"zipCode":"01310100",
102	                 "region":"%s","shippingMethod":"%s",%s"paymentMethod":"%s","installments":%d,"clubTier":"%s"}
103	                """.formatted(items, region, shipping, coupon == null ? "" : "\"coupon\":\"" + coupon + "\",",
104	                payment, installments, tier);
105	    }
