107	    private void assertSummary(Reply r, String subtotal, String discount, String shipping, int days, String insurance,
108	                               String adjustment, String total, int installments, String installment, String credit,
109	                               boolean gift) {
110	        assertThat(r.status()).isIn(200, 201);
111	        Map<String, Object> s = r.json().containsKey("summary") ? r.map("summary") : r.json();
112	        assertThat(new BigDecimal(s.get("productsSubtotal").toString())).isEqualByComparingTo(subtotal);
113	        assertThat(new BigDecimal(s.get("couponDiscount").toString())).isEqualByComparingTo(discount);
114	        assertThat(new BigDecimal(s.get("shippingCost").toString())).isEqualByComparingTo(shipping);
115	        assertThat(s.get("deliveryDays")).isEqualTo(days);
116	        assertThat(new BigDecimal(s.get("insurance").toString())).isEqualByComparingTo(insurance);
117	        assertThat(new BigDecimal(s.get("paymentAdjustment").toString())).isEqualByComparingTo(adjustment);
118	        assertThat(new BigDecimal(s.get("finalTotal").toString())).isEqualByComparingTo(total);
119	        assertThat(s.get("installments")).isEqualTo(installments);
120	        assertThat(new BigDecimal(s.get("installmentAmount").toString())).isEqualByComparingTo(installment);
121	        assertThat(new BigDecimal(s.get("nextPurchaseCredit").toString())).isEqualByComparingTo(credit);
122	        assertThat(s.get("gift")).isEqualTo(gift);
123	    }
