269	    private List<Map<String, Object>> notifications() throws Exception {
270	        HttpResponse<String> raw = http.send(HttpRequest.newBuilder(
271	                URI.create("http://localhost:" + port + "/customers/12345678909/notifications")).build(),
272	                HttpResponse.BodyHandlers.ofString());
