278	    private Map<String, Object> register(String sku, int quantity, String tier) throws Exception {
279	        Reply r = call("POST", "/orders", purchase("[{\"sku\":\"" + sku + "\",\"quantity\":" + quantity + "}]",
280	                "STORE_PICKUP", null, "PIX", 1, tier, "SOUTH"));
281	        assertThat(r.status()).isEqualTo(201);
282	        assertThat(r.json().get("status")).isEqualTo("AWAITING_PAYMENT");
283	        assertThat(r.json().get("trackingCode")).isNull();
284	        return r.json();
285	    }
