292	    @Test
293	    void fullLifeCycleWithCreditAndNotifications() throws Exception {
294	        Map<String, Object> order = register("CAM-001", 2, "SILVER");
295	        String id = order.get("id").toString();
296	        assertThat(new BigDecimal(call("GET", "/customers/12345678909", null).json().get("creditBalance").toString())).isEqualByComparingTo("0.00");
297	
298	        assertThat(call("POST", "/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}").json())
299	                .containsEntry("error", "OPERATION_NOT_ALLOWED");
300	
301	        Reply paid = call("POST", "/orders/" + id + "/payment", PAY);
302	        assertThat(paid.status()).isEqualTo(200);
303	        assertThat(paid.json().get("status")).isEqualTo("PAID");
304	        assertThat(call("GET", "/products/CAM-001", null).json().get("stock")).isEqualTo(48);
305	        // 2% of 159.80
306	        assertThat(new BigDecimal(call("GET", "/customers/12345678909", null).json().get("creditBalance").toString())).isEqualByComparingTo("3.20");
307	
308	        // same notice again: same answer, nothing done twice
309	        Reply again = call("POST", "/orders/" + id + "/payment", PAY);
310	        assertThat(again.status()).isEqualTo(200);
311	        assertThat(call("GET", "/products/CAM-001", null).json().get("stock")).isEqualTo(48);
312	        assertThat(new BigDecimal(call("GET", "/customers/12345678909", null).json().get("creditBalance").toString())).isEqualByComparingTo("3.20");
313	        // another transaction on an order that is no longer waiting
314	        assertThat(call("POST", "/orders/" + id + "/payment",
315	                "{\"transactionId\":\"OTHER\",\"paidAt\":\"2026-10-14T16:00:00Z\"}").status()).isEqualTo(409);
316	
317	        assertThat(call("POST", "/orders/" + id + "/delivery", null).status()).isEqualTo(409);
318	        assertThat(call("POST", "/orders/" + id + "/shipment", "{}").json()).containsEntry("error", "INVALID_ORDER");
319	        Reply shipped = call("POST", "/orders/" + id + "/shipment", "{\"trackingCode\":\"BR123456789\"}");
320	        assertThat(shipped.json()).containsEntry("status", "SHIPPED").containsEntry("trackingCode", "BR123456789");
321	        assertThat(call("POST", "/orders/" + id + "/cancellation", null).status()).isEqualTo(409);
322	        assertThat(call("POST", "/orders/" + id + "/delivery", null).json()).containsEntry("status", "DELIVERED");
323	
324	        assertThat(notifications()).extracting(n -> (Object) n.get("type")).containsExactly("PAYMENT_APPROVED", "ORDER_SHIPPED");
325	    }
