327	    @Test
328	    void notificationsAreListedAndMarkedRead() throws Exception {
329	        Map<String, Object> order = register("CAM-001", 1, "BRONZE");
330	        String id = order.get("id").toString();
331	        call("POST", "/orders/" + id + "/payment", PAY);
332	        call("POST", "/orders/" + id + "/cancellation", null);
333	
334	        HttpResponse<String> raw = http.send(HttpRequest.newBuilder(
335	                URI.create("http://localhost:" + port + "/customers/12345678909/notifications")).build(),
336	                HttpResponse.BodyHandlers.ofString());
337	        List<?> list = mapper.readValue(raw.body(), List.class);
338	        assertThat(list).hasSize(2);
339	        Map<?, ?> first = (Map<?, ?>) list.get(0);
340	        Map<?, ?> second = (Map<?, ?>) list.get(1);
341	        assertThat(first.get("type")).isEqualTo("PAYMENT_APPROVED");
342	        assertThat(second.get("type")).isEqualTo("ORDER_CANCELLED");
343	        assertThat(first.get("status")).isEqualTo("NEW");
344	        assertThat(first.get("orderId")).isEqualTo(id);
345	
346	        for (int i = 0; i < 2; i++) {
347	            assertThat(call("POST", "/notifications/" + first.get("id") + "/read", null).json())
348	                    .containsEntry("status", "READ");
349	        }
350	        assertThat(call("POST", "/notifications/nope/read", null).json())
351	                .containsEntry("error", "NOTIFICATION_NOT_FOUND");
352	        assertThat(call("GET", "/customers/000/notifications", null).json())
353	                .containsEntry("error", "CUSTOMER_NOT_FOUND");
354	    }
