379	    @Test
380	    void paymentWindowIs48HoursInclusive() throws Exception {
381	        Map<String, Object> exact = register("CAM-001", 1, "BRONZE");
382	        Reply ok = call("POST", "/orders/" + exact.get("id") + "/payment",
383	                payAt(exact, java.time.Duration.ofHours(48)));
384	        assertThat(ok.status()).isEqualTo(200);
385	
386	        Map<String, Object> late = register("CAM-001", 1, "BRONZE");
387	        String body = payAt(late, java.time.Duration.ofHours(48).plusSeconds(1));
388	        Reply expired = call("POST", "/orders/" + late.get("id") + "/payment", body);
389	        assertThat(expired.status()).isEqualTo(409);
390	        assertThat(expired.json()).containsEntry("error", "ORDER_EXPIRED");
391	        assertThat(call("GET", "/orders/" + late.get("id"), null).json()).containsEntry("status", "CANCELLED");
392	        // the repeated notice gets the same refusal
393	        assertThat(call("POST", "/orders/" + late.get("id") + "/payment", body).json())
394	                .containsEntry("error", "ORDER_EXPIRED");
395	        assertThat(call("GET", "/products/CAM-001", null).json().get("stock")).isEqualTo(49);
396	    }
