   108	    private PaymentResult doConfirmPayment(String id, String transactionId, String paidAtText) {
   109	        StoredOrder stored = lock(id);
   110	        Instant paidAt = parseInstant(paidAtText);
   111	        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
   112	            throw ApiException.unprocessable("INVALID_ORDER");
   113	        }
   114	        String previous = orders.findPaymentOutcome(id, transactionId).orElse(null);
   115	        if (previous != null) {
   116	            return PAYMENT_OK.equals(previous)
   117	                    ? new PaymentResult(stored.order(), null)
   118	                    : new PaymentResult(null, ApiException.conflict(previous));
   119	        }
   120	        requireTransition(stored, OrderStatus.PAID);
   121	
   122	        Order order = stored.order();
   123	        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
   124	            return refuse(stored, transactionId, "ORDER_EXPIRED");
   125	        }
   126	        // lock in a fixed order so that concurrent payments cannot deadlock
   127	        List<Order.Item> items = order.items().stream().sorted(Comparator.comparing(Order.Item::sku)).toList();
   128	        boolean enough = true;
   129	        for (Order.Item item : items) {
   130	            enough &= products.lockStock(item.sku()) >= item.quantity();
   131	        }
   132	        if (!enough) {
   133	            return refuse(stored, transactionId, "INSUFFICIENT_STOCK");
   134	        }
   135	        items.forEach(i -> products.decrementStock(i.sku(), i.quantity()));
   136	        orders.updateStatus(id, OrderStatus.PAID);
   137	        orders.recordPaymentOutcome(id, transactionId, PAYMENT_OK);
   138	        StoredOrder paid = reload(id);
   139	        listeners.forEach(l -> l.onPaid(paid));
   140	        return new PaymentResult(paid.order(), null);
   141	    }
   142	
   143	    private PaymentResult refuse(StoredOrder stored, String transactionId, String code) {
   144	        orders.recordPaymentOutcome(stored.order().id(), transactionId, code);
   145	        cancelLocked(stored);
   146	        return new PaymentResult(null, ApiException.conflict(code));
   147	    }
   148	
   149	    /** Cancels an order whose row is already locked, giving back whatever the payment had taken. */
   150	    private void cancelLocked(StoredOrder stored) {
   151	        boolean wasPaid = stored.order().status() == OrderStatus.PAID;
   152	        if (wasPaid) {
   153	            stored.order().items().stream().sorted(Comparator.comparing(Order.Item::sku))
   154	                    .forEach(i -> products.incrementStock(i.sku(), i.quantity()));
   155	        }
   156	        orders.updateStatus(stored.order().id(), OrderStatus.CANCELLED);
   157	        StoredOrder cancelled = reload(stored.order().id());
   158	        listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
   159	    }
